#define pi acos(-1.)
#define gold (sqrt(5.) / 2. - .5)

float line(vec2 p, vec2 a, vec2 b) {
    vec2 ba = b - a;
    vec2 pa = p - a;
    ba *= clamp(dot(pa, ba) / dot(ba, ba), 0., 1.);
    return length(pa - ba);
}

float tri(vec2 u, vec2 a, vec2 b, vec2 c) {
    vec2 n = vec2(c.y - a.y, a.x - c.x);
    return dot(b - c, n) * dot(u - c, n);
}

void mainImage(out vec4 o, vec2 u) {
    vec2 r = iResolution.xy,
         a, b, c, d, e;

    u = .1 * (u - r / 2.) / r.y 
            + cos(iTime * .1 + vec2(0, 11)) * vec2(.3, .2)
            + vec2(0, .3);

    float T, i;

    a.x = -1.,
    b.x = 1.,
    c.y = tan(pi / 5.);

    for(; i++ < 9.;) {
        if(T < .5) {
            d = a + (b - a) * gold;
            e = a + (c - a) * gold;

                 if(tri(u, e, a, d) > 0.) b = a, a = d, c = e;
            else if(tri(u, c, a, d) < 0.) a = b, b = c, c = d;
            else                          a = e, b = c, c = d, T = 1.;
        }

        else {
            d = c + (a - c) * gold;

            if(tri(u, b, a, d) > 0.) c = b, b = a, a = d;
            else                     a = b, b = c, c = d, T = 0.;
        }
    }

    float border = min(
                      line(u, c, a), 
                      line(u, c, b)
                   );

    o = vec4(1.2 - border * 1200.);

    o.y = max(o.y, ++T * .3);
}

